export const articlesContent = { tr }

// EN / AR çevirileri dizi olarak tutulduğu için eşleştirme slug'a göre
// değil, SIRAYA (index) göre yapılır.
function getTranslationList(locale) {
  if (locale === 'tr') return null

  const list = articleLocaleContent[locale]
  return Array.isArray(list) ? list : null
}

export function getArticles(locale = 'tr') {
  const baseList = articlesContent.tr
  const translations = getTranslationList(locale)

  if (!translations) return baseList

  if (translations.length !== baseList.length) {
    console.warn(
      `[articlesContent] "${locale}" listesinde ${translations.length} çeviri var, ` +
        `Türkçe listede ${baseList.length} makale var. Sıralama kaymış olabilir; ` +
        'iki dizinin makale sırasını kontrol edin.'
    )
  }

  return baseList.map((item, index) => {
    const translation = translations[index]

    // Bu sıradaki çeviri bulunamazsa Türkçe içeriği koru.
    if (!translation) return item

    return {
      ...item,
      ...translation,
      slug: item.slug, // URL'deki slug her dilde Türkçe slug olur
      icon: item.icon, // ikon her dilde Font Awesome sınıfı kalır (emoji ikonlar engellenir)
      sections: translation.sections ?? item.sections,
      note: translation.note ?? item.note,
    }
  })
}

export function getArticleBySlug(slug, locale = 'tr') {
  const list = getArticles(locale)
  return (
    list.find((item) => item.slug === slug) ||
    articlesContent.tr.find((item) => item.slug === slug) ||
    null
  )
}